bisection.mfunction [root, fval, iter] = bisection(f, a, b, tol)
    if f(a) * f(b) &gt;= 0
        error(&#039;f(a) and f(b) must have opposite signs&#039;);
    end

    iter = 0;
    while (b - a) / 2 &gt; tol
        iter = iter + 1;
        c = (a + b) / 2;
        if f(c) == 0
            break;
        end
        if f(a) * f(c) &lt; 0
            b = c;
        else
            a = c;
        end
    end
    root = (a + b) / 2;
    fval = f(root);
end

