&quot;\begin{algorithm}
\caption{$\text{ConstructionPlan}(G, T)$}
\begin{algorithmic}
\REQUIRE Graph $G = (T, E)$ with nodes $T$ representing towns and weighted edges $E$ representing potential roads with weights as estimated road usage
