class ToySequenceDataset(Dataset):
  """
  Generate random sequences of integers
  """

  def __init__(
    self, num_samples=8192, seq_len=64, vocab_size=512, seed=1234, device='cpu'
  ):
    g = torch.Generator(device=device).manual_seed(seed)
    self.data = torch.randint(
      0, vocab_size, (num_samples, seq_len), generator=g, device=device
    ).cpu()
    self.vocab_size = vocab_size
    self.seq_len = seq_len

  def __len__(self):
    return self.data.size(0)

  def __getitem__(self, idx):
    return self.data[idx]

def sinusoidal_positional_embedding(max_seq, d_model, device='cpu'):
  pe = torch.zeros(max_seq, d_model, device=device)
  pos = torch.arange(0, max_seq, device=device).unsqueeze(1)
  div = torch.exp(
    torch.arange(0, d_model, 2, device=device) * (-math.log(10000.0) / d_model)
  )
  pe[:, 0::2] = torch.sin(pos * div)
  pe[:, 1::2] = torch.cos(pos * div)
  return pe  # [T, D]

class SelfAttention(nn.Module):
  def __init__(self, d_model=256, n_heads=8):
    super().__init__()
    assert d_model % n_heads == 0
    self.d = d_model
    self.h = n_heads
    self.dh = d_model // n_heads
    self.qkv = nn.Linear(d_model, 3 * d_model, bias=False)
    self.proj = nn.Linear(d_model, d_model, bias=False)

